"""Forward block evaluation for seven advanced preprocessing families."""
import os,numpy as np,pandas as pd
from catboost import CatBoostRegressor
from evaluate_crossfit_psych_profiles import load_predictions,skill
from evaluate_psych_residual_on_adaptive import fit_adaptive
from src.advanced_preprocessing import build_advanced_features,CAT_ADVANCED
from src.season_delta_features import build_snapshots,attach_season_delta

raw=pd.read_csv('data/train.csv',low_memory=False);parts={y:load_predictions(raw,y) for y in (2022,2023,2024)};r22,y22,g22,b22=parts[2022];r23,y23,g23,b23=parts[2023];r24,y24,g24,b24=parts[2024];gate23=fit_adaptive(g22,y22,b22,1520023);base={2022:b22,2023:np.clip(b23+gate23.predict(g23),1e-6,1-1e-6),2024:np.load('old/experiments/adaptive_gate_2024.npz')['p']};rows={2022:r22,2023:r23,2024:r24};ys={2022:y22,2023:y23,2024:y24};X={}
for year in rows:
 hist=raw.loc[raw.season.lt(year)];snap=build_snapshots(hist);delta=attach_season_delta(pd.DataFrame(index=rows[year].index),rows[year],snap,float(hist.control_success.mean()));X[year]=build_advanced_features(rows[year],hist,delta.season_pitcher_n.to_numpy())
blocks={'league':[c for c in X[2022] if c.startswith('league_')],'pitch_logratio':[c for c in X[2022] if c.startswith('log_')],'failure':[c for c in X[2022] if any(q in c for q in ('failure','ball_middle','strike_success','success_failure'))],'missing':[c for c in X[2022] if 'missing' in c],'season_progress':[c for c in X[2022] if any(q in c for q in ('season_','preseason_','career_to_'))],'win_expectancy':[c for c in X[2022] if any(q in c for q in ('win_','expectancy','state_expected'))],'count':[c for c in X[2022] if c.startswith(('count_','fullcount_'))]};blocks['all']=list(X[2022].columns);only=os.environ.get('ADV_BLOCK');blocks={k:v for k,v in blocks.items() if not only or k==only};scales=(.05,.1,.15,.2,.25,.3,.4,.5,1)
for tag,cols in blocks.items():
 cats=[c for c in cols if c in CAT_ADVANCED];m23=CatBoostRegressor(iterations=180,depth=3,learning_rate=.02,loss_function='RMSE',l2_leaf_reg=100,random_strength=.2,bootstrap_type='Bernoulli',subsample=.8,random_seed=160000+len(cols),thread_count=6,allow_writing_files=False,verbose=False);m23.fit(X[2022][cols],y22-base[2022],cat_features=cats);c23=m23.predict(X[2023][cols]);tr=pd.concat([X[2022][cols],X[2023][cols]],ignore_index=True);m24=CatBoostRegressor(iterations=180,depth=3,learning_rate=.02,loss_function='RMSE',l2_leaf_reg=100,random_strength=.2,bootstrap_type='Bernoulli',subsample=.8,random_seed=170000+len(cols),thread_count=6,allow_writing_files=False,verbose=False);m24.fit(tr,np.r_[y22-base[2022],y23-base[2023]],sample_weight=np.r_[np.full(len(y22),.55),np.ones(len(y23))],cat_features=cats);c24=m24.predict(X[2024][cols]);s23=np.array([skill(y23,np.clip(base[2023]+s*c23,1e-6,1-1e-6)) for s in scales]);s24=np.array([skill(y24,np.clip(base[2024]+s*c24,1e-6,1-1e-6)) for s in scales]);gain=np.minimum(s23-skill(y23,base[2023]),s24-skill(y24,base[2024]));j=int(gain.argmax());print(tag,scales[j],round(s23[j],4),round(s24[j],4),'gains',round(s23[j]-skill(y23,base[2023]),4),round(s24[j]-skill(y24,base[2024]),4),flush=True);np.savez_compressed(f'evaluation/advanced_{tag}.npz',y23=y23,p23=np.clip(base[2023]+scales[j]*c23,1e-6,1-1e-6),base23=base[2023],pitcher23=r23.pitcher_id.to_numpy(),y24=y24,p24=np.clip(base[2024]+scales[j]*c24,1e-6,1-1e-6),base24=base[2024],pitcher24=r24.pitcher_id.to_numpy(),scale=scales[j])
